document.querySelectorAll('[data-menu]').forEach(button=>{const menu=document.getElementById(button.getAttribute('aria-controls'));button.addEventListener('click',()=>{const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));menu.classList.toggle('open',!expanded)});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&button.getAttribute('aria-expanded')==='true'){button.setAttribute('aria-expanded','false');menu.classList.remove('open');button.focus()}})});
const lensTabs=[...document.querySelectorAll('[data-lens]')];function selectLens(tab,focus=false){lensTabs.forEach(item=>{const selected=item===tab;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1;document.getElementById(item.getAttribute('aria-controls')).hidden=!selected});if(focus)tab.focus()}lensTabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectLens(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%lensTabs.length;if(event.key==='ArrowLeft')next=(index-1+lensTabs.length)%lensTabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=lensTabs.length-1;if(next!==undefined){event.preventDefault();selectLens(lensTabs[next],true)}})});
const search=document.getElementById('archive-search'),filter=document.getElementById('archive-filter');if(search&&filter){const results=[...document.querySelectorAll('[data-research]')];function updateArchive(){const term=search.value.trim().toLowerCase();let count=0;results.forEach(result=>{const show=result.textContent.toLowerCase().includes(term)&&(filter.value==='all'||result.dataset.category===filter.value);result.hidden=!show;if(show)count++});document.getElementById('result-count').textContent=count===0?'No research entries match':count===1?'1 research entry matches':`${count} research entries match`;document.getElementById('no-results').hidden=count!==0}search.addEventListener('input',updateArchive);filter.addEventListener('change',updateArchive)}
const signup=document.getElementById('demo-form');if(signup){signup.addEventListener('submit',event=>{event.preventDefault();if(!signup.reportValidity())return;const address=signup.elements.email.value.trim();document.getElementById('preview-address').textContent=address;document.getElementById('preview-interest').textContent=signup.elements.interest.options[signup.elements.interest.selectedIndex].text;document.getElementById('demo-preview').hidden=false;document.getElementById('form-status').textContent='Preview created in this page only. Nothing was saved or sent. You are not subscribed.';document.getElementById('demo-preview').focus()});signup.addEventListener('reset',()=>{document.getElementById('demo-preview').hidden=true;document.getElementById('preview-address').textContent='';document.getElementById('preview-interest').textContent='';document.getElementById('form-status').textContent=''})}document.querySelectorAll('[data-print]').forEach(button=>button.addEventListener('click',()=>window.print()));
